pub const primary_table_bytes = @sizeOf(@TypeOf(primary_stage1)) + @sizeOf(@TypeOf(primary_stage2));
pub const extensions_table_bytes = @sizeOf(@TypeOf(extension_starts)) + @sizeOf(@TypeOf(extension_ranges)) + @sizeOf(@TypeOf(set_descriptors)) + @sizeOf(@TypeOf(set_members)) + @sizeOf(@TypeOf(singleton_values));
pub const table_bytes = primary_table_bytes + extensions_table_bytes;

comptime {
    if (@typeInfo(Script).@"enum".fields.len != 175) @compileError("Script count changed");
    if (primary_table_bytes != 41344 or extensions_table_bytes != 2003 or table_bytes != 43347) @compileError("Script table sizes changed");
}

pub fn script(cp: u21) Script {
    if (cp >= 0x110000) return .unknown;
    const page = primary_stage1[cp >> 7];
    return primary_stage2[(@as(usize, page) << 7) | (cp & 127)];
}

pub fn scriptExtensions(cp: u21) []const Script {
    if (cp >= 0x110000) return singleton_values[0..1];
    var low: usize = 0;
    var high: usize = extension_starts.len;
    while (low < high) {
        const middle = low + (high - low) / 2;
        if (extension_starts[middle] <= cp) low = middle + 1 else high = middle;
    }
    if (low != 0) {
        const index = low - 1;
        const item = extension_ranges[index];
        const end = @as(u32, extension_starts[index]) + @as(u32, item.length_minus_one);
        if (@as(u32, cp) <= end) {
            const descriptor = set_descriptors[item.set_id];
            const offset: usize = descriptor.offset;
            return set_members[offset .. offset + descriptor.len];
        }
    }
    const id: usize = @intFromEnum(script(cp));
    return singleton_values[id .. id + 1];
}
